---InitBackpackDataList
---初始化背吧数据列表
---@param isDelayRefreshList boolean 是否延迟刷新列表
function UICultivateEquipLevelBackpackNodeMB:InitBackpackDataList(isDelayRefreshList)
    local part       = base.GetPart(self)
    local filterType = base.GetFilterType(self)
    local t = {}
    if filterType == FilTerType.SUIT then
        t = part == 0 and base.GetAllSuitDataPartListData(self) or base.GetSuitDataPartListData(self)
    else
        ---@type EquipmentComponent
        local equipComp = self.equipComp
        if part == -1 then
            ---@param equipmentCoreDojo EquipmentCoreDojo
            base.InitCoreData(self, t, function(equipmentCoreDojo)
                return
                --- 1. 未被卡牌使用
                checkNumber(equipmentCoreDojo.playerCardId) <= 0 and
                        --- 2. 未被锁定
                        checkNumber(equipmentCoreDojo.locked) <= 0 and
                        --- 3. 核心不在自定义套装中
                        not equipComp:CheckEquipCoreOnDiySuit(equipmentCoreDojo.id)
            end)
        elseif part > 0 then
            local excludeId = checkNumber(self.excludeId)
            ---@param equipDojo EquipDojo
            ---@param equipPart number
            base.InitEquipData(self, t, function(equipDojo, equipPart)

                return
                --- 1. 未被卡牌使用
                checkNumber(equipDojo.playerCardId) <= 0 and
                        --- 2. 未被锁定
                        checkNumber(equipDojo.locked) <= 0 and
                        --- 3. 同位置
                        equipPart == part and
                        --- 4. 不是要排除的装备id
                        excludeId ~= checkNumber(equipDojo.id) and
                        --- 5. 装备不在自定义套装中
                        not equipComp:CheckEquipOnDiySuit(equipDojo.id)
            end)

        else
            ---@param equipmentCoreDojo EquipmentCoreDojo
            base.InitCoreData(self, t, function(equipmentCoreDojo)
                return
                --- 1. 未被卡牌使用
                checkNumber(equipmentCoreDojo.playerCardId) <= 0 and
                        --- 2. 未被锁定
                        checkNumber(equipmentCoreDojo.locked) <= 0 and
                        --- 3. 核心不在自定义套装中
                        not equipComp:CheckEquipCoreOnDiySuit(equipmentCoreDojo.id)
            end)

            local excludeId = checkNumber(self.excludeId)
            ---@param equipDojo EquipDojo
            ---@param equipPart number
            base.InitEquipData(self, t, function(equipDojo, equipPart)
                return
                --- 1. 未被卡牌使用
                checkNumber(equipDojo.playerCardId) <= 0 and
                        --- 2. 未被锁定
                        checkNumber(equipDojo.locked) <= 0 and
                        --- 3. 不是要排除的装备id
                        excludeId ~= checkNumber(equipDojo.id) and
                        --- 4. 装备不在自定义套装中
                        not equipComp:CheckEquipOnDiySuit(equipDojo.id)
            end)


        end


    end

    local groups = base.GetGroups(self)
    --- 刷新过滤节点
    self:RefreshFilterNode(t, groups, isDelayRefreshList)
    return t
end

---InitSuitDataPartList
---初始化套装位置数据列表
---@param suitId number
---@param ownEquipPartMap table<number, table> table<装备的位置, 在该位置上拥有的装备列表>
function UICultivateEquipLevelBackpackNodeMB:InitSuitDataPartList(ownEquipPartMap)
    local suitDataPartList = {}
    ----------------------------------------
    --- 初始化套装 装备 位置数据

    local excludeId = checkNumber(self.excludeId)
    local equipComp = self.equipComp
    ---调用父类方法
    ---@param equipDojo EquipDojo
    base.InitSuitEquipPartData(self, suitDataPartList, ownEquipPartMap, function(equipDojo)
        return
                --- 1. 未被卡牌使用
                checkNumber(equipDojo.playerCardId) <= 0 and
                --- 2. 未被锁定
                checkNumber(equipDojo.locked) <= 0 and
                --- 3. 不是要排除的装备id
                excludeId ~= checkNumber(equipDojo.id) and
                --- 4. 装备不在自定义套装中
                not equipComp:CheckEquipOnDiySuit(equipDojo.id)

    end)
    ----------------------------------------

    ----------------------------------------
    ---初始化套装 装备核心 位置数据
    ---调用父类方法
    ---@param equipmentCoreDojo EquipmentCoreDojo
    base.InitSuitEquipCorePartData(self, suitDataPartList, ownEquipPartMap, function(equipmentCoreDojo)
        return
                --- 1. 未被卡牌使用
                checkNumber(equipmentCoreDojo.playerCardId) <= 0 and
                --- 2. 未被锁定
                checkNumber(equipmentCoreDojo.locked) <= 0 and
                --- 3. 核心不在自定义套装中
                not equipComp:CheckEquipCoreOnDiySuit(equipmentCoreDojo.id)
    end)
    ----------------------------------------

    return suitDataPartList
end




