function UICultivateEquipLevelBackpackNodeMB:RefreshFilterNode(dataList)
    ---@type UICommonFilterMB
    local nodeEnv = CfUtils.GetLuaScr(self.FilterNode.gameObject, FilterNodePath)
    if nodeEnv == nil then return end
    nodeEnv:SetFilterClass(Constants.UIFilterType.EquipCultivate)
    nodeEnv:SetCallback(dataList, Bind(self, self.OnClickFilterCellAction), Constants.UISortType.EquipCultivate)
    nodeEnv:SetExtraParams({part = self.equipPart, selectFoods = self:GetSelectFoods()})
    nodeEnv:RestoreState("UICultivateEquipLevelBackpackNodeMB", Bind(self, self.OnClickFilterCellAction))

end

