---RefreshEquipGoodsNode
---@param mbEnv GoodNodeMB
---@param index number
function UICultivateEquipLevelBackpackNodeMB:RefreshGoodsNode(mbEnv, index)
    local backpackDataList = base.GetBackpackDataList(self)
    local backpackData     = backpackDataList[index]
    if not backpackData then return end

    local id               = checkNumber(backpackData.id)
    local refId            = checkNumber(backpackData.refId)
    base.RefreshGoodsNodeEnv(self, mbEnv, id, backpackData.refId, backpackData.part == self.equipPart)

    --local partType = backpackData.partType
    local idFlag = string.format("%s_%s", refId, id)
    local isSelect = self.selectFoods[idFlag] ~= nil
    mbEnv:SetCheckState(isSelect)


end

