---FastSelectCells
---@param checkCallback fun(backpackData:table):boolean 数据检查回调
---@param fastSelectRule table 快速选择规则
function UICultivateEquipLevelBackpackNodeMB:FastSelectCells(checkCallback, fastSelectRule)
    ---1. 先给根据 快速选择规则 进行筛选
    local originData       = base.GetBackpackDataList(self)
    print("originData22--->>>", #originData)
    local backpackDataList = GameUtils.GetScreenData(originData, fastSelectRule, Constants.UIFilterType.EquipCultivateFastSelect, {part = self.equipPart})
    ---2. 排序
    backpackDataList = EquipUtils.SortEquipCultivateBackpackData(backpackDataList, Constants.SortType.Quality, false, {part = self.equipPart})
    ---3. 获取当前选择数量
    local selectFoods = self:GetSelectFoods()
    local selectNum = table.count(selectFoods)
    local originSelectNum = selectNum
    local status = 1
    ---@param v table
    for i, v in ipairs(backpackDataList) do
        if checkNumber(v.locked) == 0 then
            local id = v.id
            local partType = v.partType
            local refId = v.refId
            local idFlag = string.format("%s_%s", refId, id)
            if selectFoods[idFlag] == nil then
                if not checkCallback(v) then break end
                selectNum = selectNum + 1
                self.selectFoods[idFlag] = {id = id, partType = partType}
            end
        end
    end
    if selectNum > originSelectNum then
        status = 2
    end
    self.selectEquipCount = selectNum
    self:RefreshSelectCount()

    ---4. 更新列表
    -- local groups = base.GetGroups(self)
    -- local t = base.GetBackpackDataList(self, true)
    self:RefreshScrollView(originData)
    -- print("---->>>", #t)
    -- self:RefreshFilterNode(base.GetBackpackDataList(self, true), groups)
    return status
end

---RemoveSuitDataPartListByIds
---根据传入的ids 移除 套装缓存数据
---@param ids table<number, number>
function UICultivateEquipLevelBackpackNodeMB:RemoveSuitDataPartListByIds(ids, part)
    if self.filterType ~= FilTerType.SUIT then return end
    ---@type EquipmentComponent
    local equipComp = self.equipComp
    for i, id in pairs(ids) do
        if part ~= -1 then
            local equipDojo = equipComp:GetEquipById(id)
            local equipVo = cardConfMgr:GetEquipVoById(equipDojo.equipmentId)
            part = equipVo.part
        end
        base.RemoveSuitDataPartListData(self, id, part)

    end
end

