function UICultivateEquipLevelBackpackNodeMB:OnClickCellAction(eventData)
    local selectedObject   = eventData.selectedObject
    local dataIndex        = selectedObject:GetComponent(IDType).id
    local backpackDataList = base.GetBackpackDataList(self)
    local backpackData     = backpackDataList[dataIndex]
    local id               = backpackData.id
    local partType         = backpackData.partType
    local refId            = backpackData.refId
    local idFlag           = string.format("%s_%s", refId, id)
    local isSelect = self:GetSelectFoods()[idFlag] == nil
    -- if isSelect and self.selectEquipCount >= self.maxSelectCount then
    --     GameUtils.Toast(localize("已达到最大选择数量"))
    --     return
    -- end
    
    
    if isSelect and not self.clickCellCheckCallback() then return end

    self.selectFoods[idFlag] = isSelect and {id = id, partType = partType} or nil
    self.selectEquipCount = self.selectEquipCount + (isSelect and 1 or -1)
    self:RefreshSelectCount()
    base.RefreshCellShowStateByIndex(self, dataIndex, isSelect)

    if self.cellClickCallBack then
        self.cellClickCallBack(backpackData, isSelect, false, backpackData.partType)
    end
end

function UICultivateEquipLevelBackpackNodeMB:OnLongTapCellAction(eventData)
    local selectedObject   = eventData.selectedObject
    local dataIndex        = selectedObject:GetComponent(IDType).id
    local backpackDataList = base.GetBackpackDataList(self)
    local backpackData     = backpackDataList[dataIndex]
    local id               = backpackData.id
    local partType         = backpackData.partType
    local part = -1
    if partType == EQUIP_TYPE.Equip then
        ---@type EquipVo
        local equipVo = cardConfMgr:GetEquipVoById(backpackData.refId)
        part = equipVo.part
    end
    local equipPart        = self.equipPart
    local compareId
    if equipPart == part then
        compareId = self.excludeId
    end

    if self.cellLongTapCallback then
        self.cellLongTapCallback(id, compareId, partType, part)
    end

end

function UICultivateEquipLevelBackpackNodeMB:OnClickFilterCellAction(data)
    base.SetBackpackDataList(self, data)
    if not self.isDelayRefreshList then
        base.RefreshScrollView(self, data)
    end
    self.isDelayRefreshList = nil
end


